 function zoomAt(mult,x=state.w/2,y=state.h/2){const newZoom=Math.max(.65,Math.min(14,state.zoom*mult)),newScale=state.fit*newZoom;const wx=(x-state.tx)/state.scale,wy=(y-state.ty)/state.scale;state.zoom=newZoom;state.scale=newScale;state.tx=x-wx*newScale;state.ty=y-wy*newScale;requestDraw();}
