  const confirmed=parts.length,worldLoot=DB.items[id]?.worldLoot,hinted=D.buildings.filter(b=>b.rewards.includes(id));
  const observed=observedKeySource(id);if(observed)parts.push(`<article class="dependency-method"><b>Случайная находка</b><p>${esc(observed)}</p><p class="observation-note">По игровому опыту игрока. Точный шанс выпадения неизвестен.</p></article>`);
  if(worldLoot)parts.push(`<article class="dependency-method"><b>Объект лута в мире</b><p>В игре есть такой объект${[worldLoot.countMax>1?(worldLoot.countMin===worldLoot.countMax?price(worldLoot.countMax):price(worldLoot.countMin)+'–'+price(worldLoot.countMax))+' шт':'',worldLoot.takeMs?'взятие '+worldLoot.takeMs/1000+' сек':''].filter(Boolean).map((v,n)=>(n?', ':': ')+v).join('')}.</p></article>`);
  if(hinted.length)parts.push(`<article class="dependency-method"><b>Можно найти в локациях</b><p class="small-note">Игра называет этот предмет для этих зданий. Конкретный контейнер и вероятность неизвестны.</p>${hinted.map(buildingRow).join('')}</article>`);
